const e = $('Error Trigger').first().json || {};
const wf = e.workflow || {};
const ex = e.execution || {};
const err = ex.error || e.error || {};

// The ECMS execution id travels on the envelope, so a failure can be joined back to the
// ECMS row rather than living only in n8n's execution list.
let executionId = null;
let eventId = null;
let eventType = null;
try {
  const data = ex.data && ex.data.resultData && ex.data.resultData.runData;
  const guard = data && (data['Verify + Dedupe'] || data['ECMS Trigger']);
  const first = guard && guard[0] && guard[0].data && guard[0].data.main && guard[0].data.main[0];
  const json = first && first[0] && first[0].json;
  const envelope = json && (json.body || json);
  if (envelope) {
    executionId = envelope.executionId || null;
    eventId = envelope.eventId || null;
    eventType = envelope.eventType || null;
  }
} catch (ignored) {
  // A failure handler that can itself fail is not a failure handler.
}

return [{
  json: {
    workflowId: wf.id || null,
    workflowName: wf.name || null,
    n8nExecutionId: ex.id || null,
    n8nExecutionUrl: ex.url || null,
    failedNode: (err.node && err.node.name) || null,
    message: err.message || 'unknown error',
    lastNodeExecuted: ex.lastNodeExecuted || null,
    executionId,
    eventId,
    eventType,
    at: new Date().toISOString(),
  },
}];
